import React, { useContext, useState } from 'react';
import { Container, Row, Col, Table, Badge, Button } from 'reactstrap';
import { useNavigate } from 'react-router-dom';
import useFetch from '../hooks/useFetch';
import { BASE_URL } from '../utils/config';
import { AuthContext } from '../context/AuthContext';
import CommonSection from '../share/CommonSection';
import '../style/mybooking.css';

const MyBookings = () => {
   const { user } = useContext(AuthContext);
   const [refreshFlag, setRefreshFlag] = useState(0);
   const navigate = useNavigate();

   const currentUser = user?.data ? user.data : user;
   const userId = currentUser?._id;

   const { data: bookings, loading, error } = useFetch(`${BASE_URL}/booking/user/${userId}?refresh=${refreshFlag}`);

   const cancelBooking = async (id) => {
      const token = localStorage.getItem('token');
      if (!window.confirm('Bạn có chắc chắn muốn huỷ booking này?')) return;

      try {
         const res = await fetch(`${BASE_URL}/booking/${id}/cancel`, {
            method: 'PATCH',
            headers: {
               'Content-Type': 'application/json',
               Authorization: `Bearer ${token}`,
            },
            body: JSON.stringify({ reason: 'Khách yêu cầu hủy' }),
         });
         const result = await res.json();
         if (!res.ok) {
            return alert(result.message || 'Không thể huỷ booking');
         }
         alert(result.message);
         setRefreshFlag(prev => prev + 1);
      } catch (err) {
         alert(err.message || 'Lỗi kết nối');
      }
   };

   return (
      <>
         <CommonSection title={'Tour của tôi'} />

         <section>
            <Container>
               <Row>
                  <Col lg='12'>
                     {loading && <h4 className="text-center pt-5">Đang tải dữ liệu...</h4>}
                     {error && <h4 className="text-center pt-5 text-danger">{error}</h4>}

                     {!loading && !error && bookings?.length === 0 && (
                        <div className="text-center pt-5">
                           <i className="ri-emotion-sad-line" style={{ fontSize: '4rem', color: '#ff7e1a' }}></i>
                           <h4 className="mt-3">Bạn chưa đặt tour nào!</h4>
                        </div>
                     )}

                     {!loading && !error && bookings?.length > 0 && (
                        <div className="booking_list mt-4">
                           <Table hover responsive className="shadow-sm">
                              <thead className="bg-light">
                                 <tr>
                                    <th>STT</th>
                                    <th>Tên Tour</th>
                                    <th>Người đặt</th>
                                    <th>Số người</th>
                                    <th>Ngày khởi hành</th>
                                    <th>Tổng tiền</th>
                                    <th>Trạng thái</th>
                                    <th>Hành động</th>
                                 </tr>
                              </thead>
                              <tbody>
                                 {bookings.map((item, index) => {
                                    const isCancelable = item.status !== 'Đã hủy' && item.status !== 'Hoàn thành';
                                    return (
                                       <tr key={item._id}>
                                          <td>{index + 1}</td>
                                          <td className="fw-bold text-primary">{item.tourName}</td>
                                          <td>{item.fullName}</td>
                                          <td>{item.guestSize} người</td>
                                          <td>{item.bookingAt ? new Date(item.bookingAt).toLocaleDateString('vi-VN') : 'N/A'}</td>
                                          <td className="fw-bold text-success">
                                             {Number(item.totalPrice || 0).toLocaleString('vi-VN')}đ
                                          </td>
                                          <td>
                                             <Badge color={item.status === 'Đã hủy' ? 'danger' : item.status === 'Đã thanh toán' ? 'success' : 'warning'} pill>
                                                {item.status}
                                             </Badge>
                                          </td>
                                          <td>
                                             <div className="d-flex gap-2 flex-wrap justify-content-center">
                                                {isCancelable && (
                                                   <Button color="danger" size="sm" onClick={() => cancelBooking(item._id)}>
                                                      Hủy
                                                   </Button>
                                                )}
                                                {item.status === 'Đã thanh toán' && (
                                                   <Button color="primary" size="sm" onClick={() => navigate(`/voucher/${item._id}`)}>
                                                      Xem voucher
                                                   </Button>
                                                )}
                                             </div>
                                          </td>
                                       </tr>
                                    );
                                 })}
                              </tbody>
                           </Table>
                        </div>
                     )}
                  </Col>
               </Row>
            </Container>
         </section>
      </>
   );
};

export default MyBookings;
